CREATE OR REPLACE FUNCTION public.pm_asset_get(p_key text, p_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.pm_accounts%rowtype;
  allowed boolean := false;
  asset jsonb;
begin
  if coalesce(p_key, '') = '' then return null; end if;

  select a.* into account
  from public.pm_sessions s
  join public.pm_accounts a on a.login_id = s.login_id
  where s.token_hash = public.pm_token_hash(p_token)
    and s.expires_at > now()
    and a.active
  limit 1;

  if account.role in ('main', 'general') then
    allowed := true;
  elsif p_key ~ '^(branch|notice|case|intro|event)-' then
    -- 홈페이지에 공개되는 이미지 키는 거대한 JSON 검색 없이 바로 허용합니다.
    allowed := true;
  elsif account.role = 'customer' then
    -- A message mentioning a key does not grant access to that private photo.
    allowed := public.pm_storage_can_read_private(p_key, p_token);
  end if;

  if not allowed then
    raise exception 'ASSET_FORBIDDEN' using errcode = 'P0001';
  end if;

  select a.payload into asset
  from public.pm_assets a
  where a.asset_key = p_key;

  -- 마이그레이션 전에 누락된 키가 있을 때만 기존 저장소를 한 번 조회합니다.
  if asset is null then
    select sd.payload->p_key into asset
    from public.site_data sd
    where sd.data_key = 'pm-assets';
  end if;
  return asset;
end
$function$

CREATE OR REPLACE FUNCTION public.pm_storage_can_read_private(p_key text, p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  account public.pm_accounts%rowtype;
begin
  if nullif(p_key, '') is null then return false; end if;
  select a.* into account
  from public.pm_sessions s
  join public.pm_accounts a on a.login_id = s.login_id
  where s.token_hash = public.pm_token_hash(p_token)
    and s.expires_at > now()
    and a.active
  limit 1;

  if account.login_id is null then return false; end if;
  if account.role in ('main', 'general') then return true; end if;
  if account.role <> 'customer' then return false; end if;

  return exists(
    select 1
    from public.site_data sd
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(sd.payload) = 'array' then sd.payload else '[]'::jsonb end
    ) run
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(run->'steps') = 'array' then run->'steps' else '[]'::jsonb end
    ) step
    where sd.data_key = 'pm-service-runs'
      and ((run->>'memberId' = account.login_id or run#>>'{customer,id}' = account.login_id)
      and coalesce(nullif(run->>'memberId', ''), account.login_id) = account.login_id
      and coalesce(nullif(run#>>'{customer,id}', ''), account.login_id) = account.login_id)
      and step->>'approved' = 'true'
      and (case when jsonb_typeof(step->'photoKeys') = 'array' then step->'photoKeys' else '[]'::jsonb end) ? p_key
  );
end;
$function$
